{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C43"],
      "claim": "In volunteers, oral codeine phosphate 30 mg showed near-complete systemic availability estimated as 100% based on urinary recovery.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Codeine oral bioavailability was estimated as 84 ± 5% (range 74–94%) from published pharmacokinetic data.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Absolute oral bioavailability of codeine in healthy volunteers was reported as 42–71%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Even in postoperative patients, absolute oral bioavailability of codeine was 40 (22)%, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Codeine sulfate oral bioavailability in healthy subjects was 80.5%, supporting high systemic availability for the codeine core.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Codeine oral bioavailability in humans is consistently reported above 20%, with most estimates between 40% and 90%, so the query is predicted high for F ≥ 20%.",
  "evidence_gaps": [
    "Fasted-state condition is not explicitly reported in most source studies; estimates come from mixed or unspecified prandial states.",
    "Some estimates are model-derived or systemic-availability values rather than strict absolute bioavailability measurements."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

